fn claim(&self, key: &str, doc: Doc) -> bool {
    let present = self.sessions.lock().unwrap().contains_key(key);
    if !present {
        return false;
    }
    self.sessions.lock().unwrap().remove(key);
    self.gradings.lock().unwrap().insert(key.to_string(), doc);
    true
}

fn split(open: usize, due: usize, mine: usize, fresh: usize) -> (usize, usize) {
    let mine = mine.min(due);
    let kept = fresh.min(open.div_ceil(2));
    let other = (due - mine).min((fresh + mine).max(1));
    let n_due = (mine + other).min(open - kept);
    let n_fresh = fresh.min(open - n_due);
    (n_due, n_fresh)
}

fn main() {
    println!("{:?}", split(4, 6, 2, 3));
}

use std::collections::BTreeSet;

struct Review { id: String, due: u32 }

fn compose(mut reviews: Vec<Review>, related: &BTreeSet<String>) -> Vec<Review> {
    // `reviews` arrives sorted by `due`, earliest first.
    // Goal: reviews whose id is in `related` come first,
    // and within each group the due order is kept.
    reviews.sort_unstable_by_key(|r| !related.contains(&r.id));
    reviews
}
